<script setup lang="ts">
import{ref,watch,onMounted,onBeforeUnmount}from'vue';import{useSalesScope}from'./use-sales-scope';import{qualityRecordEntry,type QualityRecordEntry}from'./quality-source-entry';
const props=defineProps<{staff:any;clinicId:string;date:string;entry?:QualityRecordEntry|null;blocked?:boolean}>(),emit=defineEmits(['selected','unauthorized','access-lost','return-quality','context-change']);
const input=ref(''),source=ref<any>(null),loading=ref(false),error=ref(''),generation=ref(0),context=()=>JSON.stringify([props.staff.accountId,props.staff.employeeId,props.clinicId,props.date]),scope=useSalesScope(context);let controller:AbortController|null=null;
function clear(){generation.value++;controller?.abort();controller=null;source.value=null;loading.value=false;error.value='';emit('context-change');}
watch(input,clear,{flush:'sync'});
async function load(internal=false){if((props.blocked&&!internal)||!props.clinicId)return;clear();const id=input.value.trim().toLowerCase();if(!/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/.test(id)){error.value='请粘贴完整病历编号。';return;}const current=scope.begin('source',()=>JSON.stringify([input.value,generation.value])),own=new AbortController();controller=own;loading.value=true;const timer=setTimeout(()=>own.abort(),15000);try{const r=await fetch('/api/v1/clinical/records/'+id+'/source?'+new URLSearchParams({clinicId:props.clinicId}),{credentials:'same-origin',signal:own.signal}),b=await r.json().catch(()=>({}));if(!current())return;if(!r.ok){if(r.status===401)emit('unauthorized');if(r.status===403)emit('access-lost');throw Error(b.message||'原病历读取失败。');}if(b.record?.id!==id||b.visit?.clinicId!==props.clinicId||typeof b.visit?.id!=='string'||!(/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/.test(b.visit.id))||!Number.isFinite(Date.parse(b.record.clinicalAt))||b.canClinical!==true||!Number.isSafeInteger(b.record.version)||b.record.version<1)throw Error('病历回复与当前定位不匹配，未显示。');source.value=b;emit('selected',b);}catch(e){if(current())error.value=e instanceof Error?e.message:'原病历读取失败。';}finally{clearTimeout(timer);if(current.active())loading.value=false;if(controller===own)controller=null;}}
async function initial(){clear();input.value='';if(!props.entry)return;try{const target=qualityRecordEntry(props.entry);if(target.clinicId!==props.clinicId)return;input.value=target.recordId;await load();}catch(e){error.value=e instanceof Error?e.message:'病历定位无效。';}}
watch(()=>JSON.stringify([context(),props.entry]),()=>{void initial();},{flush:'sync'});
function back(){if(!props.blocked&&!loading.value&&props.entry)emit('return-quality');}
function isCurrent(value:any){return!!source.value&&source.value.record.id===value?.record?.id&&source.value.visit.id===value?.visit?.id&&source.value.visit.clinicId===value?.visit?.clinicId&&source.value.record.version===value?.record?.version;}
onMounted(initial);onBeforeUnmount(clear);defineExpose({refresh:()=>load(true),invalidate:clear,isCurrent});
</script>
<template><section class="b-card record-source"><h2>按编号定位原病历</h2><p>负责或参与本次就诊的医护可输入完整病历编号，按当前诊所核对原就诊。定位跨实际到院日期，不改变病历时间或归属。</p><form @submit.prevent="load()"><label>病历完整编号<input v-model="input" maxlength="36" autocomplete="off" :disabled="blocked||loading"/></label><button class="b-button outline" :disabled="blocked||loading||!clinicId">{{loading?'正在定位…':'定位 / 重读原病历'}}</button></form><p v-if="!source&&!loading&&!error">请先输入编号并定位。</p><div v-if="error" class="b-alert error" role="alert">{{error}}</div><p v-if="source">病历 {{source.record.id}} · 当前第{{source.record.version}}版 · 诊疗实际时间 {{new Date(source.record.clinicalAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}<br/>对应就诊 {{source.visit.id}}</p><p v-if="source&&entry?.recordId===source.record.id&&entry.version!==source.record.version" class="b-alert warning">原病历已更新（问题查看时第{{entry.version}}版）；下方显示当前记录，请返回资料问题重新核实。</p><button v-if="entry" class="b-button outline" :disabled="blocked||loading" @click="back">返回原资料问题</button></section></template>
<style scoped>.record-source{padding:24px;margin:20px 0}.record-source form{display:flex;align-items:end;gap:14px;flex-wrap:wrap;margin:18px 0}.record-source label{flex:1;min-width:240px}.record-source p{line-height:1.9;overflow-wrap:anywhere}</style>
